globalThis.QUESTION_PART_12 = [
  {id:'c1-01',chapter:1,topic:'Khái niệm kiểm thử',level:'Cơ bản',question:'Phát biểu nào mô tả đầy đủ nhất về kiểm thử phần mềm?',options:['Một tập hợp hoạt động nhằm phát hiện khiếm khuyết và đánh giá chất lượng sản phẩm phần mềm','Hoạt động chạy chương trình chỉ sau khi lập trình xong','Hoạt động sửa toàn bộ mã nguồn gây lỗi','Một thủ tục chứng minh phần mềm hoàn toàn không có lỗi'],answer:0,explanation:'Kiểm thử bao gồm nhiều hoạt động để phát hiện khiếm khuyết và đánh giá chất lượng, kể cả khi chưa chạy chương trình.',source:'SOTE_W01b • trang 5'},
  {id:'c1-02',chapter:1,topic:'Đối tượng kiểm thử',level:'Cơ bản',question:'Tài liệu nào có thể là đối tượng kiểm thử ngay trước khi có mã nguồn?',options:['Chỉ tệp thực thi đã biên dịch','Yêu cầu và bản thiết kế phần mềm','Chỉ báo cáo doanh thu sau triển khai','Chỉ các màn hình đã chạy được'],answer:1,explanation:'Yêu cầu, user story và thiết kế đều là sản phẩm công việc có thể được kiểm thử tĩnh.',source:'SOTE_W01b • trang 5–6'},
  {id:'c1-03',chapter:1,topic:'Kiểm thử tĩnh và động',level:'Vận dụng',question:'Nhóm đọc đặc tả và phát hiện hai yêu cầu mâu thuẫn mà không chạy ứng dụng. Đây là hoạt động nào?',options:['Kiểm thử động','Gỡ lỗi','Kiểm thử tĩnh','Kiểm thử tải'],answer:2,explanation:'Kiểm thử tĩnh kiểm tra sản phẩm công việc mà không thực thi phần mềm; review yêu cầu là ví dụ điển hình.',source:'SOTE_W01b • trang 6'},
  {id:'c1-04',chapter:1,topic:'Kiểm thử tĩnh và động',level:'Vận dụng',question:'Tester nhập số tiền 50.000.000 đồng vào ứng dụng rồi so sánh thông báo nhận được với kết quả mong đợi. Đây là gì?',options:['Phân tích nguyên nhân gốc','Review tài liệu','Phân tích tĩnh','Kiểm thử động'],answer:3,explanation:'Kiểm thử động thực thi phần mềm với đầu vào và so sánh kết quả thực tế với kết quả mong đợi.',source:'SOTE_W01b • trang 6'},
  {id:'c1-05',chapter:1,topic:'Mục tiêu kiểm thử',level:'Cơ bản',question:'Kết quả kiểm thử giúp người quản lý ra quyết định phát hành chủ yếu bằng cách nào?',options:['Cung cấp thông tin về chất lượng và rủi ro còn lại','Bảo đảm chắc chắn không có failure khi sử dụng','Thay thế mọi quyết định kinh doanh','Loại bỏ nhu cầu sửa defect'],answer:0,explanation:'Kiểm thử cung cấp thông tin và giảm rủi ro để các bên liên quan quyết định phát hành.',source:'SOTE_W01b • trang 8, 12'},
  {id:'c1-06',chapter:1,topic:'Kiểm thử và gỡ lỗi',level:'Cơ bản',question:'Hoạt động nào thuộc debugging (gỡ lỗi)?',options:['Thiết kế dữ liệu kiểm thử biên','Tìm nguyên nhân của failure rồi sửa defect','Ghi nhận kết quả thực tế khi chạy test','So sánh yêu cầu với kết quả mong đợi'],answer:1,explanation:'Gỡ lỗi tìm nguyên nhân gây failure và loại bỏ defect; kiểm thử phát hiện failure và đánh giá chất lượng.',source:'SOTE_W01b • trang 9'},
  {id:'c1-07',chapter:1,topic:'Error, defect, failure',level:'Vận dụng',question:'Lập trình viên hiểu nhầm cụm “tối đa 3 lần” thành “ít hơn 3 lần”. Hành động hiểu nhầm này là gì?',options:['Failure','Defect','Error','Test oracle'],answer:2,explanation:'Error là hành động sai của con người. Mã nguồn sai tạo ra từ cách hiểu đó mới là defect.',source:'SOTE_W01b • trang 15–16'},
  {id:'c1-08',chapter:1,topic:'Error, defect, failure',level:'Vận dụng',question:'Đặc tả cho phép amount ≤ 50.000.000 nhưng mã nguồn viết amount < 50.000.000. Điều kiện sai trong mã là gì?',options:['Failure','Root cause đã được chứng minh','Error của người dùng','Defect'],answer:3,explanation:'Defect là khiếm khuyết trong sản phẩm công việc, ở đây là điều kiện so sánh sai trong mã nguồn.',source:'SOTE_W01b • trang 15–16'},
  {id:'c1-09',chapter:1,topic:'Error, defect, failure',level:'Vận dụng',question:'Khi chạy ứng dụng, giao dịch đúng hạn mức lại bị từ chối. Hiện tượng quan sát được này là gì?',options:['Failure','Error','Test basis','Root cause'],answer:0,explanation:'Failure là sự kiện hệ thống không thực hiện đúng điều cần làm trong lúc vận hành.',source:'SOTE_W01b • trang 15–16'},
  {id:'c1-10',chapter:1,topic:'Nguyên nhân gốc',level:'Vận dụng',question:'Sau điều tra, nhóm xác định quy trình không review yêu cầu khiến hạn mức mơ hồ được đưa vào lập trình. Việc thiếu review được xem là gì?',options:['Kết quả kiểm thử mong đợi','Nguyên nhân gốc của vấn đề','Failure ở giao diện','Dữ liệu kiểm thử không hợp lệ'],answer:1,explanation:'Nguyên nhân gốc là lý do nền tảng làm vấn đề xuất hiện; xử lý nó giúp ngăn tái diễn.',source:'SOTE_W01b • trang 15–16'},
  {id:'c1-11',chapter:1,topic:'Defect và failure',level:'Cơ bản',question:'Vì sao một defect có thể tồn tại nhưng chưa gây ra failure trong lần chạy hiện tại?',options:['Vì defect chỉ tồn tại trong tài liệu','Vì mọi defect đều được hệ điều hành tự sửa','Vì đoạn mã có defect chưa được chạy trong điều kiện kích hoạt phù hợp','Vì test đã pass thì defect không thể tồn tại'],answer:2,explanation:'Defect thường chỉ gây failure khi phần mã liên quan được thực thi với điều kiện kích hoạt thích hợp.',source:'SOTE_W01b • trang 17'},
  {id:'c1-12',chapter:1,topic:'Kết quả kiểm thử sai lệch',level:'Vận dụng',question:'Một test báo fail do kỳ vọng của test viết sai, trong khi phần mềm thực hiện đúng yêu cầu. Đây là trường hợp nào?',options:['True positive','False negative','Defect clustering','False positive'],answer:3,explanation:'False positive là test báo failure nhưng thực tế không có defect tương ứng trong phần mềm.',source:'SOTE_W01b • trang 17'},
  {id:'c1-13',chapter:1,topic:'Kết quả kiểm thử sai lệch',level:'Vận dụng',question:'Phần mềm có defect nhưng bộ test vẫn báo pass vì không kiểm tra điều kiện kích hoạt. Đây là gì?',options:['False negative','False positive','Debugging','Validation'],answer:0,explanation:'False negative là test không phát hiện được defect đang tồn tại và báo pass.',source:'SOTE_W01b • trang 17'},
  {id:'c1-14',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Nhóm chạy 500 test đều pass rồi kết luận “phần mềm chắc chắn không còn lỗi”. Nguyên lý nào trực tiếp bác bỏ kết luận này?',options:['Kiểm thử phụ thuộc ngữ cảnh','Kiểm thử chỉ cho thấy sự hiện diện của lỗi, không chứng minh sự vắng mặt của lỗi','Lỗi thường tập trung','Kiểm thử sớm tiết kiệm chi phí'],answer:1,explanation:'Test pass làm giảm rủi ro nhưng không chứng minh phần mềm hoàn toàn không có defect.',source:'SOTE_W01b • trang 20'},
  {id:'c1-15',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Một chức năng có hàng triệu tổ hợp đầu vào. Nhóm chọn lớp tương đương và giá trị biên thay vì thử mọi tổ hợp. Nguyên lý nào giải thích lựa chọn này?',options:['Kiểm thử sớm','Ngộ nhận không có lỗi','Kiểm thử toàn bộ là không thể','Test bị mòn'],answer:2,explanation:'Số tổ hợp có thể quá lớn, nên cần chọn bộ test có chủ đích thay vì cố kiểm thử vét cạn.',source:'SOTE_W01b • trang 20, 22'},
  {id:'c1-16',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Tester tham gia review yêu cầu trước khi lập trình bắt đầu. Cách làm này thể hiện nguyên lý nào?',options:['Test bị mòn','Lỗi thường tập trung','Kiểm thử phụ thuộc ngữ cảnh','Kiểm thử sớm tiết kiệm thời gian và chi phí'],answer:3,explanation:'Phát hiện sai sót từ yêu cầu giúp tránh lan truyền defect sang thiết kế, mã và môi trường triển khai.',source:'SOTE_W01b • trang 20'},
  {id:'c1-17',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Phần lớn lỗi nghiêm trọng nằm trong module thanh toán nên nhóm tăng kiểm thử ở module này. Nguyên lý phù hợp nhất là gì?',options:['Lỗi thường tập trung','Kiểm thử toàn bộ luôn thực hiện được','Test pass chứng minh không có lỗi','Kiểm thử chỉ bắt đầu sau lập trình'],answer:0,explanation:'Defect thường tập trung ở một số ít khu vực; thông tin này giúp tập trung nỗ lực theo rủi ro.',source:'SOTE_W01b • trang 20'},
  {id:'c1-18',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Nhóm lặp lại bộ test cũ nhiều tháng và hầu như không tìm được lỗi mới. Hành động nào phù hợp với nguyên lý “test bị mòn”?',options:['Dừng hoàn toàn kiểm thử hồi quy','Rà soát và bổ sung tình huống, dữ liệu kiểm thử mới','Giữ nguyên test vì đã pass nhiều lần','Chỉ đổi tên các test hiện có'],answer:1,explanation:'Lặp lại đúng bộ test cũ thường tìm ít lỗi mới hơn; cần cập nhật test theo thay đổi và hiểu biết mới.',source:'SOTE_W01b • trang 21'},
  {id:'c1-19',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Ứng dụng ngân hàng ưu tiên tính đúng đắn giao dịch, còn trò chơi chú trọng trải nghiệm và phản hồi. Điều này minh họa điều gì?',options:['Mọi dự án phải dùng cùng một bộ test','Chỉ phần mềm ngân hàng cần kiểm thử','Kiểm thử phụ thuộc ngữ cảnh','Kiểm thử động thay thế được mọi review'],answer:2,explanation:'Mục tiêu, rủi ro và lĩnh vực sử dụng khác nhau dẫn đến cách kiểm thử khác nhau.',source:'SOTE_W01b • trang 21'},
  {id:'c1-20',chapter:1,topic:'Bảy nguyên lý',level:'Vận dụng',question:'Ứng dụng đáp ứng toàn bộ đặc tả nhưng quá khó dùng nên khách hàng không thể hoàn thành công việc. Nguyên lý nào giải thích thất bại này?',options:['Lỗi thường tập trung','Test bị mòn','Kiểm thử toàn bộ là không thể','Ngộ nhận về việc không có lỗi'],answer:3,explanation:'Phần mềm ít defect theo đặc tả vẫn có thể thất bại nếu không đáp ứng nhu cầu và mục đích sử dụng thật.',source:'SOTE_W01b • trang 21'},
  {id:'c1-21',chapter:1,topic:'Chất lượng, QA và QC',level:'Cơ bản',question:'Hoạt động nào thuộc đảm bảo chất lượng (QA) theo định hướng quy trình?',options:['Thiết lập chuẩn review và đào tạo nhóm để phòng ngừa lỗi','Chạy test đăng nhập trên một bản build','Ghi nhận giao dịch bị tính tiền hai lần','So sánh ảnh giao diện với thiết kế'],answer:0,explanation:'QA tập trung cải tiến quy trình và phòng ngừa defect qua tiêu chuẩn, đào tạo và các mô hình trưởng thành.',source:'SOTE_W01b • trang 24'},
  {id:'c1-22',chapter:1,topic:'Chất lượng, QA và QC',level:'Cơ bản',question:'Quan hệ nào giữa kiểm thử và kiểm soát chất lượng (QC) là phù hợp?',options:['QC chỉ là viết tài liệu quy trình','Kiểm thử là một hình thức chính của QC nhằm phát hiện vấn đề trong sản phẩm','Kiểm thử chỉ thuộc QA và không liên quan QC','QC bảo đảm mọi sản phẩm không còn lỗi'],answer:1,explanation:'QC hướng vào sản phẩm và phát hiện defect; kiểm thử tĩnh và động là các hoạt động chính của QC.',source:'SOTE_W01b • trang 24'},
  {id:'c1-23',chapter:1,topic:'Verification và validation',level:'Vận dụng',question:'Tester kiểm tra màn hình chuyển khoản có đúng giới hạn và bố cục đã ghi trong đặc tả hay không. Đây chủ yếu là gì?',options:['Validation','Đánh giá mức ưu tiên','Verification','Phân tích nguyên nhân gốc'],answer:2,explanation:'Verification kiểm tra sản phẩm có được xây dựng đúng theo đặc tả và thiết kế hay không.',source:'SOTE_W01b • trang 25'},
  {id:'c1-24',chapter:1,topic:'Verification và validation',level:'Vận dụng',question:'Khách hàng thử chuyển tiền trên điện thoại để xác nhận ứng dụng thực sự phù hợp công việc hằng ngày. Đây chủ yếu là gì?',options:['Phân tích tĩnh','Verification','Gỡ lỗi','Validation'],answer:3,explanation:'Validation đánh giá sản phẩm có đáp ứng nhu cầu người dùng và mục đích sử dụng thực tế hay không.',source:'SOTE_W01b • trang 25'},
  {id:'c1-25',chapter:1,topic:'Tư duy người kiểm thử',level:'Vận dụng',question:'Một lập trình viên chỉ chọn dữ liệu mà họ biết mã của mình xử lý tốt. Thiên kiến nào có thể xuất hiện?',options:['Thiên kiến xác nhận','Phân cụm defect','Kiểm thử hồi quy','Tính truy vết'],answer:0,explanation:'Thiên kiến xác nhận khiến người viết mã tập trung chứng minh mã hoạt động thay vì chủ động tìm điều kiện làm nó sai.',source:'SOTE_W01b • trang 28'},
  {id:'c1-26',chapter:1,topic:'Giao tiếp và báo lỗi',level:'Vận dụng',question:'Cách diễn đạt nào phù hợp nhất khi báo lỗi cho đồng đội?',options:['Bạn lại viết sai phần kiểm tra dữ liệu rồi','Chuyển khoản đúng 50.000.000 đồng bị từ chối với mã E102','Mã của bạn quá kém nên hệ thống bị lỗi','Chức năng này sai hết, tự kiểm tra lại đi'],answer:1,explanation:'Báo lỗi nên nêu sự kiện có thể kiểm chứng, tránh quy trách nhiệm hoặc phán xét người viết mã.',source:'SOTE_W01b • trang 28'},
  {id:'c1-27',chapter:1,topic:'Severity và priority',level:'Vận dụng',question:'Tên ngân hàng bị viết sai ở trang đăng nhập sắp ra mắt: ảnh hưởng chức năng thấp nhưng cần sửa ngay. Phân loại nào phù hợp?',options:['Severity cao, priority thấp','Severity cao, priority cao','Severity thấp, priority cao','Severity thấp, priority thấp'],answer:2,explanation:'Severity đo mức ảnh hưởng; priority đo mức khẩn cấp sửa. Lỗi thương hiệu có thể cần sửa gấp dù ít ảnh hưởng chức năng.',source:'SOTE_W01b • trang 18'},
  {id:'c1-28',chapter:1,topic:'Test oracle',level:'Vận dụng',question:'Trong bài săn lỗi Swag Labs, nhóm lặp lại thao tác với standard_user rồi so sánh các tài khoản khác. standard_user đóng vai trò gì?',options:['Công cụ tự động sửa lỗi','Bằng chứng chắc chắn hệ thống không có defect','Dữ liệu ngẫu nhiên không có kỳ vọng','Nguồn tham chiếu để xác định kết quả mong đợi (test oracle)'],answer:3,explanation:'Hành vi tham chiếu của standard_user giúp nhóm hình thành kỳ vọng để so sánh; nguồn tham chiếu cũng cần được xem xét hợp lý.',source:'SOTE_W01_Practice • mục 5.2, 6.2'},
  {id:'c1-29',chapter:1,topic:'Báo lỗi tái hiện được',level:'Vận dụng',question:'Một bug note có tiêu đề và ảnh chụp nhưng người khác không biết làm thế nào để gặp lại lỗi. Nội dung nào cần bổ sung trước tiên?',options:['Các bước tái hiện cụ thể cùng kết quả mong đợi và thực tế','Tên người chịu trách nhiệm bị phỏng đoán','Danh sách tất cả lỗi của dự án','Số lượng dòng mã trong module'],answer:0,explanation:'Bug note phải đủ rõ để người khác tái hiện và hiểu sai lệch giữa mong đợi với thực tế.',source:'SOTE_W01b • trang 35; SOTE_W01_Practice • mục 5.5'},
  {id:'c1-30',chapter:1,topic:'Trách nhiệm chất lượng',level:'Cơ bản',question:'Phát biểu nào phù hợp với cách tiếp cận cả nhóm về chất lượng?',options:['Tester tự chịu trách nhiệm về mọi defect của sản phẩm','Chất lượng là trách nhiệm của cả nhóm phát triển sản phẩm','Developer chỉ cần chạy được chương trình, không cần quan tâm test','Quản lý có thể bỏ qua chất lượng nếu mọi test đều pass'],answer:1,explanation:'Developer, tester và các vai trò khác cùng tạo ra chất lượng; tester không thể một mình bảo đảm chất lượng.',source:'SOTE_W01b • trang 7, 29'},
  {id:'c2-01',chapter:2,topic:'Quy trình kiểm thử',level:'Cơ bản',question:'Mô tả nào đúng về các nhóm hoạt động kiểm thử trong dự án Agile?',options:['Chỉ được thực hiện một lần theo chuỗi không được lặp','Không cần lập kế hoạch nếu đã có test tự động','Có thể chồng lấp và lặp lại; giám sát, kiểm soát diễn ra xuyên suốt','Chỉ bắt đầu sau khi hoàn thành toàn bộ sản phẩm'],answer:2,explanation:'Các hoạt động kiểm thử không phải chuỗi cứng nhắc; chúng có thể lặp và chồng lấp theo ngữ cảnh.',source:'SOTE_W02 • trang 6–7'},
  {id:'c2-02',chapter:2,topic:'Lập kế hoạch',level:'Vận dụng',question:'Nhóm xác định mục tiêu test, tiêu chí kết thúc và ước lượng ba tester làm trong hai tuần. Đây là hoạt động nào?',options:['Thực thi kiểm thử','Phân tích kiểm thử','Hoàn tất kiểm thử','Lập kế hoạch kiểm thử'],answer:3,explanation:'Mục tiêu, cách tiếp cận, tiêu chí vào/ra và ước lượng nguồn lực thuộc lập kế hoạch.',source:'SOTE_W02 • trang 8'},
  {id:'c2-03',chapter:2,topic:'Giám sát và kiểm soát',level:'Vận dụng',question:'Ngày thứ năm chỉ chạy được 40% số test; quản lý chuyển thêm một tester sang module chuyển tiền. Đây là gì?',options:['Giám sát và kiểm soát kiểm thử','Thiết kế dữ liệu kiểm thử','Gỡ lỗi chương trình','Đóng toàn bộ defect'],answer:0,explanation:'So sánh tiến độ với kế hoạch là giám sát; điều chỉnh nhân lực để xử lý chậm trễ là kiểm soát.',source:'SOTE_W02 • trang 9'},
  {id:'c2-04',chapter:2,topic:'Phân tích kiểm thử',level:'Vận dụng',question:'Khi đọc yêu cầu hạn mức chuyển tiền, tester hỏi “Hạn mức có bao gồm phí không?” và xác định các điều kiện cần test. Đây là hoạt động nào?',options:['Thực thi kiểm thử','Phân tích kiểm thử','Chuẩn bị môi trường','Hoàn tất kiểm thử'],answer:1,explanation:'Phân tích nghiên cứu test basis, phát hiện vấn đề trong nó và xác định điều kiện kiểm thử: cần kiểm thử cái gì.',source:'SOTE_W02 • trang 10'},
  {id:'c2-05',chapter:2,topic:'Thiết kế kiểm thử',level:'Vận dụng',question:'Tester biến điều kiện “tại hạn mức” thành test gửi 50.000.000 đồng, mong đợi giao dịch thành công. Đây là gì?',options:['Theo dõi tiến độ','Chuẩn bị tài khoản test','Thiết kế kiểm thử','Hoàn tất kiểm thử'],answer:2,explanation:'Thiết kế chuyển điều kiện kiểm thử thành test case cụ thể, bao gồm dữ liệu và kết quả mong đợi.',source:'SOTE_W02 • trang 11'},
  {id:'c2-06',chapter:2,topic:'Triển khai kiểm thử',level:'Vận dụng',question:'Nhóm tạo tài khoản với số dư biết trước, chuẩn bị script đặt lại cơ sở dữ liệu và nhóm test thành suite. Đây là hoạt động nào?',options:['Phân tích yêu cầu','Lập báo cáo hoàn tất','Xác định nguyên nhân gốc','Triển khai kiểm thử (test implementation)'],answer:3,explanation:'Test implementation chuẩn bị thủ tục, script, suite, dữ liệu và môi trường sẵn sàng cho việc chạy test.',source:'SOTE_W02 • trang 12'},
  {id:'c2-07',chapter:2,topic:'Thực thi kiểm thử',level:'Vận dụng',question:'Tester chạy TC-12, so sánh actual với expected, ghi log và báo lỗi khi giao dịch bị từ chối. Đây là gì?',options:['Thực thi kiểm thử','Thiết kế kiểm thử','Lập kế hoạch','Cải tiến mô hình trưởng thành'],answer:0,explanation:'Chạy test, so sánh kết quả, ghi log và báo bất thường thuộc test execution.',source:'SOTE_W02 • trang 13'},
  {id:'c2-08',chapter:2,topic:'Hoàn tất kiểm thử',level:'Cơ bản',question:'Hoạt động nào phù hợp nhất với giai đoạn hoàn tất kiểm thử?',options:['Chỉ định đầu vào cho một test case mới','Lưu trữ testware, ghi bài học và lập báo cáo hoàn tất','Chạy test đầu tiên của sprint','Tạo dữ liệu số dư trước khi chạy suite'],answer:1,explanation:'Test completion tổng kết, giải quyết trạng thái defect, lưu testware và ghi nhận bài học cho lần sau.',source:'SOTE_W02 • trang 14'},
  {id:'c2-09',chapter:2,topic:'Truy vết',level:'Vận dụng',question:'Trong ma trận truy vết, yêu cầu xuất PDF không được liên kết với test case nào. Điều gì được chỉ ra trực tiếp?',options:['Chức năng xuất PDF chắc chắn có defect','Mọi test đều cần chạy lại','Một khoảng trống về độ bao phủ yêu cầu','Yêu cầu xuất PDF không còn cần thiết'],answer:2,explanation:'Thiếu liên kết tới test case cho thấy yêu cầu chưa được bao phủ bởi bộ test đang ghi nhận, không tự chứng minh có defect.',source:'SOTE_W02 • trang 17–18'},
  {id:'c2-10',chapter:2,topic:'V-model',level:'Vận dụng',question:'Trong V-model, khi nào có thể bắt đầu thiết kế kiểm thử chấp nhận?',options:['Chỉ sau khi kiểm thử hệ thống hoàn tất','Chỉ khi đã có bản triển khai production','Chỉ sau khi toàn bộ unit test pass','Ngay khi các yêu cầu liên quan được phê duyệt'],answer:3,explanation:'Nhánh phải thể hiện thời điểm chạy test; lập kế hoạch, phân tích và thiết kế có thể bắt đầu song song với phát triển.',source:'SOTE_W02 • trang 26–28'},
  {id:'c2-11',chapter:2,topic:'Agile và SDLC',level:'Vận dụng',question:'Một nhóm Scrum phát hành mỗi hai tuần. Cách tổ chức kiểm thử nào phù hợp nhất?',options:['Tester tham gia nhóm từ đầu và kiểm thử trong từng sprint','Đợi hết mọi sprint mới bắt đầu test','Dồn test vào một sprint riêng sau khi code xong','Chỉ chạy test khi khách hàng báo lỗi'],answer:0,explanation:'Trong Scrum, phát triển và kiểm thử diễn ra hằng ngày trong sprint; tester làm việc trong nhóm từ ngày đầu.',source:'SOTE_W02 • trang 30'},
  {id:'c2-12',chapter:2,topic:'Cấp độ kiểm thử',level:'Vận dụng',question:'Kiểm thử riêng hàm tính phí chuyển tiền, cô lập khỏi phần còn lại của hệ thống, thuộc cấp độ nào?',options:['Kiểm thử hệ thống','Kiểm thử thành phần (component)','Kiểm thử chấp nhận','Kiểm thử tích hợp hệ thống'],answer:1,explanation:'Component testing kiểm thử một đơn vị riêng lẻ như hàm, lớp hoặc module trong điều kiện cô lập.',source:'SOTE_W02 • trang 35, 37'},
  {id:'c2-13',chapter:2,topic:'Cấp độ kiểm thử',level:'Vận dụng',question:'Nhóm kiểm tra dữ liệu mà module Chuyển tiền gửi sang module Tài khoản trong cùng ứng dụng. Đây là cấp độ nào?',options:['Kiểm thử chấp nhận','Kiểm thử thành phần','Kiểm thử tích hợp thành phần','Kiểm thử tích hợp hệ thống với bên ngoài'],answer:2,explanation:'Tích hợp thành phần kiểm tra giao tiếp và tương tác giữa các đơn vị bên trong hệ thống.',source:'SOTE_W02 • trang 35–36, 46'},
  {id:'c2-14',chapter:2,topic:'Cấp độ kiểm thử',level:'Vận dụng',question:'Tester kiểm tra toàn bộ luồng đăng nhập, chuyển tiền và xem biên nhận trên ứng dụng hoàn chỉnh theo yêu cầu. Đây chủ yếu là cấp độ nào?',options:['Kiểm thử thành phần','Kiểm thử tích hợp thành phần','Kiểm thử tĩnh','Kiểm thử hệ thống'],answer:3,explanation:'System testing đánh giá toàn bộ hệ thống với yêu cầu, bao gồm các công việc end-to-end.',source:'SOTE_W02 • trang 43, 46'},
  {id:'c2-15',chapter:2,topic:'Cấp độ kiểm thử',level:'Vận dụng',question:'MiniBank kết nối nhà cung cấp SMS bên ngoài để gửi OTP. Kiểm thử sự tương tác này thuộc cấp độ nào?',options:['Kiểm thử tích hợp hệ thống','Kiểm thử thành phần','Kiểm thử tích hợp thành phần nội bộ','Kiểm thử chấp nhận của người dùng'],answer:0,explanation:'System integration testing tập trung giao tiếp giữa hệ thống đang xét với các hệ thống hoặc dịch vụ bên ngoài.',source:'SOTE_W02 • trang 44, 46'},
  {id:'c2-16',chapter:2,topic:'Kiểm thử chấp nhận',level:'Vận dụng',question:'Nhân viên ngân hàng thử các nghiệp vụ thật để xác nhận phần mềm phù hợp nhu cầu công việc. Hình thức nào phù hợp nhất?',options:['Kiểm thử tải','Kiểm thử chấp nhận của người dùng (UAT)','Kiểm thử thành phần','Phân tích tĩnh'],answer:1,explanation:'UAT để người dùng đánh giá hệ thống có phù hợp công việc và nhu cầu thực tế hay không.',source:'SOTE_W02 • trang 45–46'},
  {id:'c2-17',chapter:2,topic:'Kiểm thử chấp nhận',level:'Vận dụng',question:'Đội vận hành kiểm tra có khôi phục được dữ liệu từ bản sao lưu ban đêm hay không. Đây là hình thức chấp nhận nào?',options:['Beta testing','Alpha testing','Kiểm thử chấp nhận vận hành (OAT)','Kiểm thử chấp nhận hợp đồng'],answer:2,explanation:'OAT đánh giá khả năng vận hành như sao lưu, khôi phục và các nhu cầu của quản trị hệ thống.',source:'SOTE_W02 • trang 45'},
  {id:'c2-18',chapter:2,topic:'Driver và stub',level:'Vận dụng',question:'Khi kiểm thử hàm confirm, nhóm thay dịch vụ OTP bằng một đối tượng giả trả lời đúng/sai có kiểm soát. Đối tượng giả đó là gì?',options:['Driver gọi toàn bộ suite','Báo cáo test completion','Cổng SMS production','Stub'],answer:3,explanation:'Stub thay thành phần được đối tượng kiểm thử gọi; nó cho phản hồi có kiểm soát mà không cần dịch vụ thật.',source:'SOTE_W02 • trang 38, 41'},
  {id:'c2-19',chapter:2,topic:'Chiến lược tích hợp',level:'Cơ bản',question:'Chiến lược tích hợp từ trên xuống (top-down) thường cần gì để thay các thành phần cấp dưới chưa sẵn sàng?',options:['Stub','Báo cáo nghiệm thu','Dữ liệu khách hàng production','Chỉ driver và không cần thành phần thay thế'],answer:0,explanation:'Top-down bắt đầu từ thành phần cấp cao và dùng stub thay các thành phần được gọi ở cấp thấp hơn.',source:'SOTE_W02 • trang 42'},
  {id:'c2-20',chapter:2,topic:'Cấp độ và loại kiểm thử',level:'Cơ bản',question:'Phân loại nào đúng khi lập ma trận kiểm thử?',options:['Performance là cấp độ, System là loại','System là cấp độ, Performance là loại kiểm thử','Regression là cấp độ, Component là loại','Acceptance và Security đều là cấp độ'],answer:1,explanation:'Cấp độ mô tả phạm vi đối tượng và mục tiêu theo lớp kiểm thử; loại như performance mô tả khía cạnh được kiểm tra.',source:'SOTE_W02 • trang 49–50; SOTE_W02_Practice • mục 4.3'},
  {id:'c2-21',chapter:2,topic:'Kiểm thử phi chức năng',level:'Vận dụng',question:'Nhóm đo xem 95% yêu cầu tìm kiếm có trả về dưới 2 giây với 200 người đồng thời không. Đây chủ yếu là loại nào?',options:['Kiểm thử tính đúng đắn chức năng','Kiểm thử thành phần như một loại chất lượng','Kiểm thử hiệu năng','Kiểm thử chấp nhận hợp đồng trong mọi trường hợp'],answer:2,explanation:'Thời gian phản hồi dưới tải xác định là thuộc tính hiệu năng, tức khía cạnh phi chức năng.',source:'SOTE_W02 • trang 49, 52; SOTE_W02_Practice • mục 4.2'},
  {id:'c2-22',chapter:2,topic:'Hộp đen và hộp trắng',level:'Cơ bản',question:'Nguồn chính để thiết kế test hộp trắng là gì?',options:['Chỉ phản hồi của người dùng cuối','Chỉ đặc tả nghiệp vụ, không xem mã','Chỉ ảnh chụp giao diện','Cấu trúc và mã bên trong phần mềm'],answer:3,explanation:'Hộp trắng dựa vào cấu trúc nội bộ, ví dụ câu lệnh và nhánh; hộp đen dựa vào đặc tả.',source:'SOTE_W02 • trang 53'},
  {id:'c2-23',chapter:2,topic:'Confirmation và regression',level:'Vận dụng',question:'Sau khi sửa BUG-07, tester chạy lại đúng TC-12 vốn đã fail để xem lỗi đã được sửa chưa. Đây là gì?',options:['Kiểm thử xác nhận sửa lỗi (confirmation)','Kiểm thử tải','Kiểm thử độ tương thích','Kiểm thử tích hợp như một loại sau thay đổi'],answer:0,explanation:'Confirmation testing chạy lại test liên quan lỗi đã sửa để xác nhận defect được khắc phục.',source:'SOTE_W02 • trang 54'},
  {id:'c2-24',chapter:2,topic:'Confirmation và regression',level:'Vận dụng',question:'Sau khi đổi công thức tính phí, nhóm chạy lại các test chuyển tiền và số dư để xem có chức năng khác bị hỏng không. Đây là gì?',options:['Chỉ kiểm thử xác nhận','Kiểm thử hồi quy (regression)','Review tĩnh yêu cầu','Kiểm thử chấp nhận vận hành'],answer:1,explanation:'Regression kiểm tra ảnh hưởng không mong muốn của thay đổi tới những phần đã hoạt động.',source:'SOTE_W02 • trang 54–55'},
  {id:'c2-25',chapter:2,topic:'Smoke test',level:'Vận dụng',question:'Bản build mới vừa được giao; nhóm kiểm tra nhanh ứng dụng có khởi động và các chức năng chính có chạy cơ bản không trước khi test sâu. Đây là gì?',options:['Stress test','Recovery test','Smoke test','Kiểm thử vét cạn'],answer:2,explanation:'Smoke test kiểm tra nhanh khả năng hoạt động cơ bản của bản build để quyết định có thể tiếp tục test hay không.',source:'SOTE_W02 • trang 56'},
  {id:'c2-26',chapter:2,topic:'Kiểm thử bảo trì',level:'Vận dụng',question:'Ứng dụng đang sử dụng được chuyển sang cơ sở dữ liệu mới. Nhóm kiểm tra dữ liệu chuyển đổi và chạy hồi quy. Đây thuộc loại hoạt động nào?',options:['Chỉ kiểm thử trước khi có mã nguồn','Chỉ kiểm thử alpha của sản phẩm mới','Chỉ review yêu cầu không cần chạy hệ thống','Kiểm thử bảo trì do nâng cấp hoặc di chuyển'],answer:3,explanation:'Thay đổi, nâng cấp/di chuyển và ngừng hệ thống là các tác nhân kích hoạt maintenance testing.',source:'SOTE_W02 • trang 57–58'},
  {id:'c2-27',chapter:2,topic:'Shift-left',level:'Vận dụng',question:'Nhóm đưa review đặc tả, unit test và phân tích tĩnh vào sớm trong quá trình phát triển. Cách làm này gọi là gì?',options:['Shift-left','Shift-right','Big bang integration','Beta testing'],answer:0,explanation:'Shift-left đưa hoạt động kiểm thử về sớm hơn trước phát hành để nhận phản hồi và ngăn defect lan truyền.',source:'SOTE_W02 • trang 61–62'},
  {id:'c2-28',chapter:2,topic:'TDD',level:'Cơ bản',question:'Thứ tự nào đúng trong chu trình TDD được trình bày trong tài liệu?',options:['Viết hết mã → phát hành → viết test','Viết test fail → viết mã cho test pass → cải thiện cấu trúc mã','Cải thiện cấu trúc mã → bỏ test fail → phát hành','Viết test pass sẵn → ngừng sửa mã → bỏ test'],answer:1,explanation:'TDD dùng vòng Red–Green–Refactor: test thất bại trước, mã tối thiểu để pass rồi tái cấu trúc.',source:'SOTE_W02 • trang 63'},
  {id:'c2-29',chapter:2,topic:'BDD',level:'Vận dụng',question:'Kịch bản “Given có 10 triệu; When chuyển 2 triệu; Then còn 8 triệu” minh họa cách tiếp cận nào?',options:['Kiểm thử hộp trắng dựa trên nhánh','Phân tích nguyên nhân gốc','BDD mô tả hành vi bằng Given–When–Then','Kiểm thử tải bằng dữ liệu ngẫu nhiên'],answer:2,explanation:'BDD mô tả hành vi bằng ngôn ngữ nghiệp vụ theo cấu trúc điều kiện ban đầu, hành động và kết quả.',source:'SOTE_W02 • trang 64–65'},
  {id:'c2-30',chapter:2,topic:'DevOps và phản hồi tự động',level:'Cơ bản',question:'Trong pipeline DevOps minh họa ở bài học, điều gì nên xảy ra khi một kiểm thử bắt buộc bị fail?',options:['Tiếp tục phát hành vì đã build thành công','Xóa kết quả fail để pipeline xanh','Bỏ qua test đó ở mọi lần chạy sau','Dừng pipeline để nhóm xử lý vấn đề'],answer:3,explanation:'Pipeline cung cấp phản hồi nhanh trên mỗi thay đổi; test fail ngăn quy trình tiếp tục phát hành bản có vấn đề.',source:'SOTE_W02 • trang 66'}
];
